import { DomainValidationError, TaskAlreadyDoneError } from "../domain/errors";

export type ApplicationErrorKind = "not-found" | "validation" | "conflict";

export class ApplicationError extends Error {
  constructor(
    readonly kind: ApplicationErrorKind,
    message: string,
  ) {
    super(message);
    this.name = "ApplicationError";
  }
}

export function notFound(what: string, id: string): ApplicationError {
  return new ApplicationError("not-found", `${what} ${id} not found`);
}

/** Runs a domain operation, translating domain errors into application errors. */
export function translateDomainErrors<T>(operation: () => T): T {
  try {
    return operation();
  } catch (error) {
    if (error instanceof DomainValidationError) {
      throw new ApplicationError("validation", error.message);
    }
    if (error instanceof TaskAlreadyDoneError) {
      throw new ApplicationError("conflict", error.message);
    }
    throw error;
  }
}

